// Main composition — single continuous scene
const MainComposition: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: videoFps } = useVideoConfig();

  // PHASE 1: CRT Boot Flash
  const crtFlash = interpolate(
    frame,
    [0, 2, 4, 6],
    [0, 0.3, 0, 0.08],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // PHASE 5: Ambient Glow
  const settleGlow = interpolate(frame, [140, 160], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const glowPulse = Math.sin(frame * 0.12) * 0.3 + 0.7;
  const glowOpacity = settleGlow * glowPulse * 0.5;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: COLORS.bg,
        fontFamily: "'JetBrains Mono', 'Fira Code', 'SF Mono', monospace",
      }}
    >
      {/* CRT Boot Flash */}
      {crtFlash > 0.001 && (
        <AbsoluteFill
          style={{
            backgroundColor: `rgba(200,180,220,${crtFlash})`,
            zIndex: 10,
            pointerEvents: "none",
          }}
        />
      )}

      {/* Ambient Glow */}
      <AbsoluteFill
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          pointerEvents: "none",
          zIndex: 1,
        }}
      >
        <div
          style={{
            width: 900,
            height: 700,
            background: `radial-gradient(ellipse at center, rgba(192,160,216,0.35) 0%, rgba(192,160,216,0) 70%)`,
            filter: "blur(60px)",
            opacity: glowOpacity,
            borderRadius: "50%",
          }}
        />
      </AbsoluteFill>

      {/* Main Content */}
      <AbsoluteFill
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          zIndex: 5,
        }}
      >
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "flex-start",
            padding: "120px 200px",
          }}
        >
          {/* Pixel Bubble */}
          <PixelBubble />

          {/* Gap */}
          <div style={{ height: 48 }} />

          {/* INTEL: Header */}
          <IntelHeader />

          {/* Gap */}
          <div style={{ height: 24 }} />

          {/* Stat Lines */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: 8,
            }}
          >
            {STAT_LINES.map((line, i) => (
              <StatLine
                key={i}
                startFrame={line.startFrame}
                highlight={line.highlight}
                descriptor={line.descriptor}
                lineIndex={i}
              />
            ))}
          </div>
        </div>
      </AbsoluteFill>

      {/* CRT Overlays */}
      <CRTScanlines />
      <CRTFlicker />
    </AbsoluteFill>
  );
};

export default MainComposition;
